import 'package:isolate_pool_executor/isolate_pool_executor.dart';

int _doTask(int count){
  int sum=0;final r=Random();
  for(int i=0;i<count;i++) sum+=r.nextInt(10000);
  return sum;
}

void main() async{
  final pool=IsolatePoolExecutor.newFixedIsolatePool(3);
  final result=await pool.compute(_doTask,1000000);
  print(result);
  pool.shutdown();
}
